    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('I-PLAN','intro','خطط إدارة المرافق','',199,'{"text": "سبع خطط تغطي فصل إدارة المرافق والسلامة في معايير سباهي. كل خطة تُبنى مما في المنصة: إجراءاتها، ومخاطرها في السجل، ونشاطاتها في التقويم، ومؤشراتها الحية، ولجنتها. يكفي أن تفتح الخطة لترى أين تُنفَّذ وكيف تُقاس.", "points": ["لكل خطة مالك مسؤول عن تنفيذها وقياسها ورفع تقاريرها للجنة إدارة المرافق والسلامة (C-01).", "تُراجع كل خطة سنوياً في نطاقها وأهدافها وأدائها وفاعليتها، وتُعدَّل عند أي تغيير جوهري في المباني أو الخدمات.", "الخطة تطبَّق في كل منشآت التجمع، ولكل منشأة ملحق بمواقعها وأصولها الخاصة من سجل المواقع والأصول."]}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-01','plan','خطة السلامة','خطط إدارة المرافق والسلامة',201,'{"purpose": "توفير بيئة مادية آمنة للمرضى والعاملين والزوار بتحديد المخاطر في المباني والممارسات والسيطرة عليها قبل أن تسبب ضرراً.", "scope": "كل المباني والمساحات الداخلية والخارجية لمنشآت التجمع، والعاملين والمقاولين والزوار، وأعمال الإنشاء والتجديد داخل المناطق المشغّلة.", "objectives": ["تنفيذ 100٪ من جولات بيئة الرعاية المجدولة وإغلاق ملاحظاتها في مهلتها", "خفض الحوادث وشبه الحوادث في المرافق مقارنة بالعام السابق", "تهيئة 100٪ من عمالة المقاولين قبل دخولهم المواقع"], "elements": [["تقييم المخاطر", "جولات بيئة الرعاية وتحليل الحوادث ومراجعة سجل المخاطر"], ["السلامة المهنية", "معدات الوقاية، وسلامة العمل على ارتفاع والأماكن المحصورة والكهرباء"], ["سلامة المقاولين", "التهيئة والبطاقات وتصاريح العمل وحق إيقاف العمل"], ["السلامة أثناء الإنشاء والتجديد", "تقييم ICRA وتقييم مخاطر ما قبل الإنشاء والحواجز"], ["الإبلاغ والتحقيق", "كل حادث أو شبه حادث يُبلَّغ ويُحلَّل ويُتابَع إجراؤه التصحيحي"]], "procs": "F-02 · H-03 · H-07 · M-01 · G-10", "risks": "RK-03 · RK-08 · RK-09", "cal": "K-16 · K-13", "comm": "C-01", "kpis": [{"name": "إغلاق ملاحظات الجولات في مهلتها", "target": "≥ 90٪", "freq": "شهري", "source": "الجولات الميدانية (F-02)"}, {"name": "التصاريح المغلقة في وقتها", "target": "≥ 95٪", "freq": "شهري", "source": "تصريح العمل", "auto": "permit_ontime"}, {"name": "الحوادث وشبه الحوادث المبلغ عنها", "target": "اتجاه تنازلي مع ارتفاع الإبلاغ", "freq": "شهري", "source": "H-03"}], "training": ["تهيئة السلامة لكل موظف جديد ولكل عامل مقاول", "تدريب مُصدري تصاريح العمل سنوياً", "الإبلاغ عن الحوادث لكل العاملين"], "records": ["تقارير الجولات وخطط تصحيحها", "سجل الحوادث والتحقيقات", "سجل تهيئة المقاولين", "تصاريح العمل المغلقة"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "SAF"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-02','plan','خطة الأمن','خطط إدارة المرافق والسلامة',202,'{"purpose": "حماية الأشخاص والممتلكات والمعلومات في المنشآت، وضبط الدخول للمناطق الحساسة، والاستجابة للحوادث الأمنية.", "scope": "المداخل والمواقف والمناطق الحساسة (الولادة والأطفال، الطوارئ، الصيدلية والمستودعات، غرف الخوادم، غرف الكهرباء والغازات) وأنظمة الكاميرات وضبط الدخول.", "objectives": ["تصنيف المناطق الحساسة في كل منشأة وضبط الدخول إليها", "تشغيل أنظمة المراقبة وضبط الدخول دون أعطال تتجاوز المهلة", "تنفيذ تمرين للأمن (مثل اختطاف رضيع أو شخص عنيف) سنوياً في المنشآت ذات العلاقة"], "elements": [["تحديد المناطق الحساسة", "تقييم سنوي لكل منشأة وتحديث قائمة المناطق المقيدة"], ["ضبط الدخول والهوية", "بطاقات العاملين والمقاولين والزوار، والأبواب المقيدة"], ["الأنظمة الأمنية", "الكاميرات وضبط الدخول والإنذار، وصيانتها ضمن الصيانة الوقائية"], ["الاستجابة للحوادث الأمنية", "رموز الطوارئ الأمنية وخطة الاستجابة والإبلاغ"], ["أمن الأنظمة التقنية للمباني", "عزل أنظمة المباني المتصلة بالشبكة ومراجعة صلاحياتها"]], "procs": "H-05 · H-03 · T-05 · R-21", "risks": "RK-18 · RK-13", "cal": "K-26 · K-12", "comm": "C-01", "kpis": [{"name": "الحوادث الأمنية المبلغ عنها والمغلقة", "target": "100٪ تحقيق ومتابعة", "freq": "شهري", "source": "H-03"}, {"name": "جاهزية الكاميرات وضبط الدخول", "target": "≥ 98٪", "freq": "شهري", "source": "سجل الأصول والأعطال"}], "training": ["التعرف على الرموز الأمنية والاستجابة لها", "مراقبة الدخول للعاملين في المناطق الحساسة"], "records": ["قائمة المناطق الحساسة لكل منشأة", "سجلات الحوادث الأمنية", "مراجعات صلاحيات الدخول"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "SAF"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-03','plan','خطة المواد والنفايات الخطرة','خطط إدارة المرافق والسلامة',203,'{"purpose": "حصر المواد الخطرة واستخدامها وتخزينها والتخلص منها بأمان، وإدارة النفايات الطبية من مصدرها حتى التخلص النهائي.", "scope": "المواد الكيميائية والغازات المضغوطة والمواد المشعة والأدوية الخطرة والزئبق، والنفايات الطبية والحادة والكيميائية في كل المنشآت.", "objectives": ["جرد محدَّث للمواد الخطرة ببطاقات السلامة في كل قسم مستخدم", "الفرز من المصدر في كل الأقسام السريرية", "صفر انسكابات دون استجابة موثقة"], "elements": [["الجرد وبطاقات السلامة", "قائمة المواد لكل موقع وبطاقة بيانات السلامة متاحة"], ["التخزين والملصقات", "تخزين حسب التوافق والتهوية والملصقات الواضحة"], ["الاستجابة للانسكاب", "أطقم الانسكاب والتدريب والإبلاغ"], ["النفايات الطبية", "الفرز والنقل الداخلي والتخزين المؤقت والتسليم لمقاول مرخص بوثيقة شحن"], ["التعرض والوقاية", "معدات الوقاية وغسول العيون والدش في المواقع الخطرة"]], "procs": "H-04 · S-02 · H-03", "risks": "RK-17", "cal": "K-14", "comm": "C-01", "kpis": [{"name": "المواقع التي لديها جرد وبطاقات محدثة", "target": "100٪", "freq": "نصف سنوي", "source": "جرد المواد الخطرة (K-14)"}, {"name": "نتائج تفتيش الفرز من المصدر", "target": "≥ 95٪ مطابقة", "freq": "شهري", "source": "S-02"}], "training": ["التعامل مع المواد الخطرة وبطاقات السلامة", "الاستجابة للانسكاب", "فرز النفايات للعاملين وعمالة النظافة"], "records": ["جرد المواد الخطرة", "وثائق شحن النفايات وشهادات الإتلاف", "سجل الانسكابات"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "SAF"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-04','plan','خطة السلامة من الحريق','خطط إدارة المرافق والسلامة',204,'{"purpose": "حماية الأرواح والمنشآت من الحريق والدخان بالوقاية والكشف المبكر والإطفاء وحماية مسارات الخروج، وفق كود الحماية من الحريق السعودي واشتراطات الدفاع المدني وأكواد NFPA.", "scope": "أنظمة الإنذار والإطفاء ومضخات الحريق وأبواب ومخمدات الحريق وفواصل الحريق ومخارج الطوارئ وطفايات الحريق في كل المباني.", "objectives": ["تنفيذ 100٪ من الاختبارات الدورية لأنظمة الحريق في مواعيدها", "تمرين إخلاء لكل وردية في كل منشأة كل ربع سنة", "لا تعطيل دون سجل وإجراءات بديلة", "إغلاق ملاحظات الدفاع المدني في مهلتها"], "elements": [["منع الحريق", "ضبط الأعمال الساخنة ومصادر الاشتعال والتخزين"], ["الكشف والإنذار", "اختبار وصيانة الإنذار حسب NFPA 72"], ["الإطفاء", "الرشاشات والمضخات وصناديق الحريق والطفايات حسب NFPA 25 و10"], ["الاحتواء والمخارج", "فواصل وأبواب الحريق، ومسارات خروج خالية حسب NFPA 101"], ["التعطيل والإجراءات البديلة", "سجل التعطيل والإجراءات البديلة حتى الإعادة"], ["التدريب والتمارين", "خطة RACE/PASS وتمارين الإخلاء لكل وردية"]], "procs": "H-01 · H-02 · H-06 · M-01 · M-03", "risks": "RK-03 · RK-04", "cal": "K-02 · K-03 · K-04 · K-05 · K-11 · K-15", "comm": "C-01", "kpis": [{"name": "التعطيلات المفتوحة الآن", "target": "أقل ما يمكن ولا متأخر", "freq": "لحظي", "source": "تعطيل أنظمة الحريق", "auto": "impair_open"}, {"name": "عودة الأنظمة في موعدها", "target": "≥ 95٪", "freq": "شهري", "source": "تعطيل أنظمة الحريق", "auto": "impair_ontime"}, {"name": "تمارين الإخلاء المنفذة", "target": "100٪ من المجدول", "freq": "ربع سنوي", "source": "H-02"}], "training": ["الاستجابة للحريق واستخدام الطفايات لكل العاملين سنوياً", "أدوار الإخلاء الأفقي والرأسي للتمريض", "إجراءات التعطيل لفنيي الصيانة"], "records": ["محاضر الاختبارات الدورية", "سجلات التعطيل والدوريات", "تقارير تمارين الإخلاء وتقييمها", "تراخيص الدفاع المدني وملاحظاته"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "SAF"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-05','plan','خطة المعدات الطبية','خطط إدارة المرافق والسلامة',205,'{"purpose": "ضمان أن كل جهاز طبي في الخدمة آمن ودقيق ويعمل، من تخطيط شرائه حتى إخراجه من الخدمة، بحسب درجة خطورته.", "scope": "كل الأجهزة الطبية المملوكة والمستأجرة والمعارة في منشآت التجمع، والأجهزة المتصلة بالشبكة.", "objectives": ["لكل جهاز رقم أصل وفئة خطورة في السجل", "إنجاز 100٪ من الصيانة الوقائية للأجهزة الداعمة للحياة و≥ 90٪ لغيرها", "فحص الاستدعاءات خلال 48 ساعة"], "elements": [["السجل والتصنيف", "جرد الأجهزة وتصنيف خطورتها وتحديد ما يدعم الحياة"], ["الاستلام والتشغيل", "فحص القبول والتدريب قبل دخول الخدمة"], ["الصيانة والمعايرة", "الوقائية واختبارات السلامة الكهربائية بحسب الفئة"], ["الأعطال والوكلاء", "الاستجابة للأعطال ومتابعة أداء عقود الخدمة"], ["الاستدعاءات والتنبيهات", "فحص ومتابعة استدعاءات الشركات والهيئة"], ["الإخراج من الخدمة", "لجنة التكهين ومحو البيانات والإحلال"]], "procs": "B-01 · B-02 · B-03 · B-04 · B-05 · G-07 · G-08 · T-03", "risks": "RK-12 · RK-13", "cal": "K-20", "comm": "C-04 · C-01", "kpis": [{"name": "إنجاز الوقائية للأجهزة الداعمة للحياة", "target": "100٪", "freq": "شهري", "source": "B-02"}, {"name": "فحص الاستدعاءات خلال 48 ساعة", "target": "100٪", "freq": "شهري", "source": "B-04"}, {"name": "جاهزية الأجهزة الحرجة", "target": "≥ 95٪", "freq": "شهري", "source": "سجل الأجهزة الطبية"}], "training": ["تدريب المستخدمين عند الاستلام وعند تغيّر الطراز", "الإبلاغ عن الأعطال والحوادث المرتبطة بالأجهزة"], "records": ["سجل الأجهزة الطبية", "تقارير الصيانة والمعايرة", "سجل الاستدعاءات", "محاضر التكهين"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "BME"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-06','plan','خطة أنظمة المرافق','خطط إدارة المرافق والسلامة',206,'{"purpose": "ضمان تشغيل أنظمة المرافق الحيوية بأمان واعتمادية، وتقليل خطر توقفها، والاستعداد لانقطاعها ببدائل جاهزة وإجراءات طوارئ معروفة.", "scope": "الكهرباء والمولدات والتغذية غير المنقطعة، الغازات الطبية والتفريغ، المياه والصرف، التكييف والتهوية (بما فيها الضغط في المناطق الخاصة)، المصاعد، أنظمة إدارة المباني، والاتصالات الحيوية.", "objectives": ["حصر الأنظمة والمكونات الحرجة لكل منشأة وخرائط إغلاقها", "إنجاز ≥ 90٪ من الصيانة الوقائية في شهرها", "اختبار المولدات شهرياً تحت الحمل", "إدارة المياه للوقاية من الليجيونيلا"], "elements": [["الجرد والمخاطر", "أصول المرافق الحرجة وتقييم مخاطرها"], ["الصيانة والاختبار", "خطط وقائية بحسب الصانع والأكواد"], ["خرائط الإغلاق", "مواقع صمامات وقواطع الإغلاق لكل منطقة وتعليمات إيقافها"], ["الانقطاعات", "الإيقاف المخطط بإشعار وبديل، والطوارئ عند الانقطاع"], ["جودة الهواء والمياه", "الضغط والتغييرات الهوائية للمناطق الخاصة وخطة إدارة المياه"], ["قطع الغيار", "مخزون احتياطي للمكونات الحرجة"]], "procs": "G-05 · G-06 · M-02 · M-03 · M-04 · M-05 · G-11", "risks": "RK-01 · RK-02 · RK-05 · RK-06 · RK-10 · RK-11 · RK-16", "cal": "K-01 · K-06 · K-07 · K-08 · K-09 · K-10 · K-18 · K-24", "comm": "C-01 · C-07", "kpis": [{"name": "إنجاز الصيانة المخططة هذا الشهر", "target": "≥ 90٪", "freq": "شهري", "source": "الأعمال المخططة", "auto": "ppm_month"}, {"name": "أوامر وقائية متأخرة الآن", "target": "صفر", "freq": "لحظي", "source": "الأعمال المخططة", "auto": "ppm_late"}, {"name": "الاستجابة للطوارئ خلال ساعتين", "target": "100٪", "freq": "شهري", "source": "بلاغ طارئ", "auto": "emerg_response"}], "training": ["خرائط الإغلاق وإجراءات الطوارئ لكل فني", "التصرف عند انقطاع الكهرباء أو الغازات للتمريض في المناطق الحرجة"], "records": ["سجل الأصول وخطط الصيانة", "محاضر اختبار المولدات والأنظمة", "إشعارات الإيقاف المخطط", "نتائج فحص المياه"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "MNT"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('PL-07','plan','خطة إدارة الطوارئ','خطط إدارة المرافق والسلامة',207,'{"purpose": "جاهزية المنشآت للاستجابة للطوارئ والكوارث الداخلية والخارجية واستمرار الخدمة الأساسية والتعافي، بناءً على تحليل قابلية التأثر بالمخاطر.", "scope": "الطوارئ الداخلية (حريق، انقطاع المرافق، تسرب) والخارجية (إصابات جماعية، ظروف جوية، أوبئة) في كل المنشآت، بالتنسيق مع خطة الطوارئ في التجمع والجهات الخارجية.", "objectives": ["تحليل قابلية تأثر سنوي لكل منشأة يحدد أعلى المخاطر", "تمرينان على الأقل سنوياً لكل منشأة، أحدهما مع جهات خارجية", "تقرير تقييم لكل تمرين وحدث حقيقي بإجراءات تصحيحية"], "elements": [["تحليل قابلية التأثر", "تقييم الاحتمال والأثر والجاهزية لكل خطر سنوياً"], ["قيادة الحدث", "نظام قيادة الحوادث وأدواره ومركز العمليات"], ["الاتصالات", "قوائم الاتصال ووسائل بديلة"], ["الموارد والمخزون", "المياه والوقود والأكسجين والمستلزمات لمدة الاكتفاء المحددة"], ["السلامة والأمن أثناء الحدث", "الإخلاء وضبط الدخول"], ["المرافق والخدمات السريرية", "البدائل واستمرار الخدمات الحرجة"], ["التعافي", "العودة للتشغيل الطبيعي وتقييم ما بعد الحدث"]], "procs": "H-02 · G-11 · H-03 · R-22", "risks": "RK-01 · RK-02 · RK-06", "cal": "K-12 · K-13 · K-11", "comm": "C-01 · C-07", "kpis": [{"name": "التمارين المنفذة", "target": "2 لكل منشأة سنوياً", "freq": "نصف سنوي", "source": "H-02"}, {"name": "الإجراءات التصحيحية بعد التمارين المغلقة", "target": "≥ 90٪", "freq": "ربع سنوي", "source": "تقارير التمارين"}, {"name": "متوسط زمن إغلاق بلاغات الطوارئ", "target": "حسب نوع الحدث", "freq": "شهري", "source": "بلاغ طارئ", "auto": "emerg_close_avg"}], "training": ["أدوار نظام قيادة الحوادث للقيادات", "خطة الطوارئ والإخلاء لكل العاملين"], "records": ["تحليل قابلية التأثر", "تقارير التمارين والأحداث", "قوائم الاتصال المحدثة", "جرد المخزون الاستراتيجي"], "eval": "تقييم سنوي في ديسمبر يُعرض على لجنة إدارة المرافق والسلامة (C-01): هل ما زال النطاق مناسباً، وما الذي تحقق من الأهداف، وكيف كان الأداء في المؤشرات، وما مدى فاعلية الخطة في خفض المخاطر. وتُبنى خطة العام التالي على نتائجه (K-17، F-04).", "owner": "SAF"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('RK-17','risk','انسكاب أو تعرض لمادة خطرة أو سوء التخلص من النفايات الطبية','السلامة',158,'{"l": 3, "i": 3, "cause": "جرد غير محدث، تخزين غير متوافق، فرز ضعيف من المصدر", "effect": "إصابات للعاملين ومخالفات بيئية", "controls": ["الجرد وبطاقات السلامة (H-04، K-14)", "الفرز من المصدر (R-31)", "أطقم الانسكاب"], "plan": "تفتيش شهري مشترك للأمن والسلامة والخدمات العامة على مواقع التخزين والنفايات", "owner": "SAF", "ref": "H-04 · S-02"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('RK-18','risk','دخول غير مصرح لمنطقة حساسة','الأمن',159,'{"l": 2, "i": 4, "cause": "أبواب مقيدة معطلة، بطاقات غير مراجعة، ضعف المراقبة", "effect": "خطر على المرضى (الولادة والأطفال) أو على الأصول والأدوية", "controls": ["ضبط الدخول (H-05)", "لا دخول للمقاول بلا تهيئة وبطاقة (R-21)"], "plan": "مراجعة سنوية للمناطق الحساسة وأنظمة ضبط دخولها في كل منشأة", "owner": "SAF", "ref": "H-05"}'::jsonb) on conflict (code) do nothing;
    insert into public.seed_marks(key) values ('gov_frame_plans_v1');
